"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6809],{62601:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a lease manager over a store structure.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"name","desc":"","lua_type":"string"},{"name":"ownerServerId","desc":"Identifies this holder; leases are only renewable and releasable by their owner.","lua_type":"string"},{"name":"options","desc":"`clock` and `duration`.","lua_type":"any?"}],"returns":[{"desc":"","lua_type":"LeaseManager\\n"}],"function_type":"static","source":{"line":57,"path":"src/internal/LeaseManager.luau"}},{"name":"acquire","desc":"Takes the lease if it is free or expired, or refreshes it if this owner\\nalready holds it.","params":[{"name":"self","desc":"","lua_type":"LeaseManager"},{"name":"key","desc":"","lua_type":"string"}],"returns":[{"desc":"The lease and its epoch, or `nil` if another owner holds it.","lua_type":"Lease?"}],"function_type":"static","source":{"line":76,"path":"src/internal/LeaseManager.luau"}},{"name":"renew","desc":"Extends a lease held at a known epoch.\\n\\nFails if another owner took it, or if it was taken and returned, since the\\nepoch will have moved on.","params":[{"name":"self","desc":"","lua_type":"LeaseManager"},{"name":"key","desc":"","lua_type":"string"},{"name":"epoch","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Lease?\\n"}],"function_type":"static","source":{"line":118,"path":"src/internal/LeaseManager.luau"}},{"name":"validate","desc":"Whether this owner still holds `key` at `epoch`. A read, not a write; called\\nbefore and after anything that yields.","params":[{"name":"self","desc":"","lua_type":"LeaseManager"},{"name":"key","desc":"","lua_type":"string"},{"name":"epoch","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":143,"path":"src/internal/LeaseManager.luau"}},{"name":"release","desc":"Releases the lane immediately rather than letting it time out.\\n\\nWrites a tombstone instead of removing the key, so the next acquirer reads\\nthe stored epoch and increments it and fencing tokens stay monotonic across a\\nclean handoff.","params":[{"name":"self","desc":"","lua_type":"LeaseManager"},{"name":"key","desc":"","lua_type":"string"},{"name":"epoch","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":161,"path":"src/internal/LeaseManager.luau"}}],"properties":[],"types":[],"name":"LeaseManager","desc":"A distributed lock with a fencing token, built on compare-and-set.\\n\\nOnly the server holding a lane\'s lease scans it, which stops two servers\\nforming overlapping matches from the same tickets.\\n\\nA lease alone is not sufficient. A server can stall on a long yield, a GC\\npause or a slow web call, lose its lease to the timeout, and resume still\\nbelieving it holds one. So every lease carries a monotonically increasing\\n`epoch`, and the commit checks that epoch inside its own transform. A stalled\\nserver\'s write is then rejected by the store itself, rather than by a check\\nit could skip.\\n\\nThree properties keep the epoch meaningful:\\n\\n- Taking over an expired lease increments it, so the previous holder\'s token\\n  is permanently stale.\\n- Re-acquiring a lease you already hold keeps it, so renewal is not treated\\n  as a takeover.\\n- Releasing writes a tombstone instead of deleting the key, so the counter\\n  survives a clean handoff rather than restarting at 1.\\n\\nLeases last `LEASE_DURATION` (15 s) and are renewed every\\n`LEASE_RENEW_INTERVAL` (5 s), giving three attempts before expiry. The stored\\nrecord lives three times as long as the lease so an idle gap cannot lose the\\nepoch to expiry.","source":{"line":32,"path":"src/internal/LeaseManager.luau"}}')}}]);